method separate_paren_groups(paren_string: string) returns (result: seq<string>)
    requires paren_string != null
    // The input string should not be null.
    requires forall i :: 0 <= i < paren_string.Length ==> (paren_string[i] == '(' || paren_string[i] == ')' || paren_string[i] == ' ')
    // The input string can only contain '(', ')', and spaces.
    ensures result != null
    // The result should not be null.
    ensures forall group :: group in result ==> group.Length > 0 && 
            (forall j :: 0 <= j < group.Length ==> (group[j] == '(' || group[j] == ')')) &&
            // Each group in the result is a non-empty string containing only parentheses.
            (countOpeningParen(group) == countClosingParen(group))
            // Each group must be balanced.
    ensures result.Length > 0
    // The result should contain at least one group.
    ensures forall x :: x in result ==> exists s :: paren_string.Contains(s)
    // Each group in the result must exist in the original string.

method countOpeningParen(s: string) returns (count: int)
    // Counts the number of opening parentheses in the string.

method countClosingParen(s: string) returns (count: int)
    // Counts the number of closing parentheses in the string.
```

